function PoseMatrix({ progress }: { progress: number }) {
  const theta = 0.18 + progress * 0.42;
  const x = 1.2 + progress * 2.4;
  const y = 0.8 + Math.sin(progress * Math.PI) * 1.1;

  const values = [
    [Math.cos(theta), -Math.sin(theta), x],
    [Math.sin(theta), Math.cos(theta), y],
    [0, 0, 1]
  ];

  return (
    <div className="pose-card" aria-live="off">
      <div className="pose-heading">
        <span className="status-dot" />
        <span>ROVER POSE</span>
      </div>
      <div className="matrix-row">
        <span className="matrix-symbol">T =</span>
        <div className="matrix-brackets" aria-label="Rover pose matrix">
          {values.map((row, rowIndex) => (
            <div className="matrix-line" key={rowIndex}>
              {row.map((value, columnIndex) => (
                <span key={columnIndex}>
                  {value.toFixed(value === 0 || value === 1 ? 0 : 2)}
                </span>
              ))}
            </div>
          ))}
        </div>
        <span className="matrix-close">]</span>
      </div>
      <p className="pose-caption">
        Position and heading in the world frame.
      </p>
    </div>
  );
}

function RoverScene({ progress }: { progress: number }) {
  const roverX = 12 + progress * 62;
  const roverY = 68 - Math.sin(progress * Math.PI) * 36;
  const rotation = 12 + progress * 38;

  return (
    <div className="scene" aria-label="Animated rover navigating around obstacles">
      <svg
        className="scene-svg"
        viewBox="0 0 520 260"
        role="img"
        aria-labelledby="scene-title"
      >
        <title id="scene-title">
          A rover follows a curved path around stationary obstacles
        </title>
        <defs>
          <pattern
            id="grid"
            width="32"
            height="32"
            patternUnits="userSpaceOnUse"
          >
            <path d="M 32 0 L 0 0 0 32" className="grid-line" fill="none" />
          </pattern>
          <filter id="soft-shadow" x="-50%" y="-50%" width="200%" height="200%">
            <feDropShadow
              dx="0"
              dy="4"
              stdDeviation="5"
              floodColor="#6d88a2"
              floodOpacity=".16"
            />
          </filter>
        </defs>

        <rect width="520" height="260" rx="20" fill="url(#grid)" />

        <path
          d="M 62 190 C 110 190, 118 142, 178 142 S 250 204, 300 164 S 355 72, 436 64"
          className="path-line"
        />
        <path
          d="M 62 190 C 110 190, 118 142, 178 142 S 250 204, 300 164 S 355 72, 436 64"
          pathLength="1"
          strokeDasharray="1"
          strokeDashoffset={1 - progress}
          className="path-progress"
        />

        <g className="obstacle" filter="url(#soft-shadow)">
          <rect x="142" y="64" width="44" height="38" rx="7" />
        </g>
        <g className="obstacle" filter="url(#soft-shadow)">
          <rect x="286" y="192" width="58" height="35" rx="7" />
        </g>
        <g className="obstacle" filter="url(#soft-shadow)">
          <rect x="370" y="114" width="66" height="42" rx="7" />
        </g>

        <circle cx="62" cy="190" r="5" className="start-point" />
        <circle cx="436" cy="64" r="8" className="goal-ring" />
        <circle cx="436" cy="64" r="3" className="goal-point" />
        <text x="450" y="68" className="goal-label">Goal</text>

        <g
          transform={`translate(${roverX * 5.2}, ${roverY * 2.6}) rotate(${rotation})`}
          filter="url(#soft-shadow)"
        >
          <rect x="-25" y="-17" width="50" height="34" rx="11" className="rover-body" />
          <rect x="-33" y="-13" width="8" height="12" rx="3" className="rover-wheel" />
          <rect x="-33" y="3" width="8" height="12" rx="3" className="rover-wheel" />
          <rect x="25" y="-13" width="8" height="12" rx="3" className="rover-wheel" />
          <rect x="25" y="3" width="8" height="12" rx="3" className="rover-wheel" />
          <circle cx="2" cy="0" r="7" className="rover-camera" />
          <path d="M 5 -7 L 18 -15" className="heading-line" />
        </g>
      </svg>
      <div className="scene-footer">
        <span>PATH FOLLOWING</span>
        <span>{Math.round(progress * 100)}%</span>
      </div>
    </div>
  );
}

function RoboticsVisualization() {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    let frame = 0;
    let animationFrame = 0;
    const animate = () => {
      frame += 1;
      setProgress((frame % 900) / 900);
      animationFrame = requestAnimationFrame(animate);
    };
    animationFrame = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(animationFrame);
  }, []);

  return (
    <div className="visualization">
      <RoverScene progress={progress} />
      <PoseMatrix progress={progress} />
    </div>
  );
}

